```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, count(*) n, approx_quantile(gap_start_ms,0.5) med_start_gap_ms, approx_quantile(server_ms,0.5) med_server_ms, approx_quantile(client_ms,0.5) med_client_ms FROM (SELECT 'abn' p, c.duration/1e6 client_ms, s.duration/1e6 server_ms, (epoch_ms(s.time)-epoch_ms(c.time)) gap_start_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' AND s.service_name='geo' UNION ALL SELECT 'norm', c.duration/1e6, s.duration/1e6, (epoch_ms(s.time)-epoch_ms(c.time)) FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' AND s.service_name='geo') GROUP BY p",
          "claim": "search→geo.Geo/Nearby client spans take about 1.4 s before geo's server span starts; geo's server time stays about 0.14 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, approx_quantile(duration/1e6,0.1) p10_ms, approx_quantile(duration/1e6,0.5) p50_ms FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Client' GROUP BY span_name",
          "claim": "Every search→geo call is delayed (p10 about 1.3 s), while search→rate calls from the same pod stay around 4 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT p, service_name, metric, avg(value) avgv FROM (SELECT 'abn' p, * FROM abnormal_metrics_sum UNION ALL SELECT 'norm', * FROM normal_metrics_sum) WHERE metric IN ('k8s.pod.network.io','k8s.pod.network.errors') AND service_name IN ('search','geo') GROUP BY ALL ORDER BY 2,3,1",
          "claim": "search and geo pod network I/O and network errors are essentially unchanged between normal and abnormal periods; no packet loss signal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms, avg(duration/1e6) avg_ms FROM abnormal_traces WHERE (service_name='search' AND attr_span_kind='Server') OR (service_name='frontend' AND span_name='search.Search/Nearby') GROUP BY ALL",
          "claim": "search's server latency (~1.5 s avg) matches frontend's client calls to search.Search/Nearby, with frontend's /hotels server spans slowed to about 2.7 s p95."
        }
      ]
    }
  ]
}
```

